Lemma geo_0RB1RA_1LC0RD_1LD0RA_1RB0LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1RA_1LC0RD_1LD0RA_1RB0LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (DpCounter.cview_none_D p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB1RA_1LC0RD_1LD0RA_1RB0LD
             = (StB, (rep [S0;S0] (S j) ++ [S1;S1], S0, [S1;S1]))).
  { unfold cden, B1_0RB1RA_1LC0RD_1LD0RA_1RB0LD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S0;S0] (S j) ++ [S1;S1]) ++ [S0], S0, [S1;S1]))).
  { unfold Cc_0RB1RA_1LC0RD_1LD0RA_1RB0LD. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB1RA_1LC0RD_1LD0RA_1RB0LD. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_0RB1RA_1LC0RD_1LD0RA_1RB0LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1RA_1LC0RD_1LD0RA_1RB0LD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1RA_1LC0RD_1LD0RA_1RB0LD B0_0RB1RA_1LC0RD_1LD0RA_1RB0LD B1_0RB1RA_1LC0RD_1LD0RA_1RB0LD 4 12 p j' [] []).
    + exact run_ovf_0RB1RA_1LC0RD_1LD0RA_1RB0LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1RA_1LC0RD_1LD0RA_1RB0LD p j' E).
    + exact (geo_0RB1RA_1LC0RD_1LD0RA_1RB0LD p j' E).
    + lia.
Qed.

