Lemma bootq_0RB1RA_1LC0RD_1LD0RA_1RB0LD : stepn tmm_0RB1RA_1LC0RD_1LD0RA_1RB0LD 15 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_0RB1RA_1LC0RD_1LD0RA_1RB0LD 15 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_0RB1RA_1LC0RD_1LD0RA_1RB0LD 15 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

