(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1RA_1LC0RD_1LD0RA_1RB0LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1RA_1LC0RD_1LD0RA_1RB0LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB1RA_1LC0RD_1LD0RA_1RB0LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1RA_1LC0RD_1LD0RA_1RB0LD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1RA_1LC0RD_1LD0RA_1RB0LD : forall t, ~ In t pins_0RB1RA_1LC0RD_1LD0RA_1RB0LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB1RA_1LC0RD_1LD0RA_1RB0LD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB1RA_1LC0RD_1LD0RA_1RB0LD
      with (l := [SWin 4; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB1RA_1LC0RD_1LD0RA_1RB0LD
      with (l := [SWin 2]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_0RB1RA_1LC0RD_1LD0RA_1RB0LD
      with (l := []).
    vm_compute; reflexivity.
  - (* B1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB1RA_1LC0RD_1LD0RA_1RB0LD
      with (l := [SWin 4; SCycL 2 0; SWin 1; SWinL 2]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB1RA_1LC0RD_1LD0RA_1RB0LD
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB1RA_1LC0RD_1LD0RA_1RB0LD
      with (l := [SWin 4; SCycL 2 0; SWin 1; SWinL 3; SCycR 2; SWin 3]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_0RB1RA_1LC0RD_1LD0RA_1RB0LD
      with (l := [SWin 4; SCycL 2 0; SWin 1; SWinL 3]).
    vm_compute; reflexivity.
Qed.

