  - destruct (lapi_0RB1RB_0LC1RA_1LD0RB_1RA1LC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1RB_0LC1RA_1LD0RB_1RA1LC B0_0RB1RB_0LC1RA_1LD0RB_1RA1LC B1_0RB1RB_0LC1RA_1LD0RB_1RA1LC 4 10 p j' [] []).
