(** ** The lap *)

Lemma lap_0RB1RC_1LC0RD_1LA0LC_1RB0RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1RC_1LC0RD_1LA0LC_1RB0RD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1RC_1LC0RD_1LA0LC_1RB0RD B0_0RB1RC_1LC0RD_1LA0LC_1RB0RD B1_0RB1RC_1LC0RD_1LA0LC_1RB0RD 6 12 p j' [] []).
    + exact run_ovf_0RB1RC_1LC0RD_1LA0LC_1RB0RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1RC_1LC0RD_1LA0LC_1RB0RD p j' E).
    + exact (geo_0RB1RC_1LC0RD_1LA0LC_1RB0RD p j' E).
    + lia.
Qed.

